mapper.select:
    	select ROW_NUMBER() over (order by ocot.resource_no) as row,*  from om_cloud_optimizer_tbl ocot 
 		where resource_type >0 


		 	and ocot.resource_org_size >= 0 
 		and EXISTS(select 1 from om_cloud_resource_log_tbl ocrlt where ocot.resource_no = ocrlt.resource_no

		     	  AND CAST(rgstr_yyyy AS INTEGER) = #{rgstr_yyyy} ::INTEGER


					AND CAST(rgstr_mm AS INTEGER)  = #{rgstr_mm} ::INTEGER
				)


		 	and ocot.resource_org_size >= 0 
 		and not EXISTS(select 1 from om_cloud_resource_log_tbl ocrlt where ocot.resource_no = ocrlt.resource_no

		     	  AND CAST(rgstr_yyyy AS INTEGER) = #{rgstr_yyyy} ::INTEGER


					AND CAST(rgstr_mm AS INTEGER)  = #{rgstr_mm} ::INTEGER
				)



		 	and  0>ocot.resource_org_size








	        AND ocot.site_no IN

	            CAST(#{item} AS INTEGER)










						ORDER BY ocot.resource_type ${sortItem.dir} 


						ORDER BY ocot.resource_name ${sortItem.dir} 


						ORDER BY ocot.resource_status ${sortItem.dir} 


						ORDER BY ocot.resource_org_size  ${sortItem.dir} 


						ORDER BY ocot.resource_new_size_type2 ${sortItem.dir} 





			order by resource_no



			LIMIT #{size} OFFSET #{offset}

select resource_status, resource_name, resource_org_size, resource_new_size_type2, cloud_no, resource_type, rgstr_date, count(*) as resource_call_cnt from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE -1 END AS resource_status, resource_org_size, resource_new_size_type2, resource_name, b.cloud_no, resource_type, a.rgstr_date from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
) a where 1=1 and resource_status =1 group by resource_status, resource_name, resource_org_size, resource_new_size_type2, resource_type, cloud_no, rgstr_date order by resource_type;

select EXTRACT(YEAR FROM ocrlt.rgstr_dt) AS year, sum(otbl.resource_org_size) as resource_org_size, SUM( CASE WHEN otbl.resource_new_size_type1 != otbl.resource_new_size_type2 THEN otbl.resource_new_size_type2 ELSE 0 END ) AS resource_new_size_type2 FROM om_cloud_resource_log_tbl ocrlt INNER JOIN om_cloud_optimizer_tbl otbl ON ocrlt.resource_no = otbl.resource_no where EXTRACT(YEAR FROM ocrlt.rgstr_dt) = #{year} and otbl.resource_org_size >= 0
and ocrlt.cloud_no = #{cloud_no}
GROUP BY EXTRACT(YEAR FROM ocrlt.rgstr_dt);

select resource_status, resource_name, resource_org_size, resource_new_size_type2, cloud_no, resource_type, count(*) as resource_call_cnt from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE -1 END AS resource_status, resource_org_size, resource_new_size_type2, resource_name, b.cloud_no, resource_type from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
and a.rgstr_dd = #{rgstr_dd}
) a group by resource_status, resource_name, resource_org_size, resource_new_size_type2, resource_type, cloud_no;

select weekday, cloud_no, a.resource_no, resource_org_size, resource_new_size_type2, resource_status, count(*) as resource_call_cnt from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE -1 END AS resource_status, EXTRACT(ISODOW FROM a.rgstr_dt) AS weekday, a.cloud_no, a.resource_no, resource_org_size, resource_new_size_type2 from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
) a group by weekday,cloud_no,a.resource_no,resource_org_size, resource_new_size_type2, resource_status order by weekday

select resource_name, a.resource_no, resource_org_size, resource_new_size_type2, resource_status, count(*) as resource_call_cnt ,cloud_no from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE 0 END AS resource_status, a.resource_no, b.resource_name, resource_org_size, resource_new_size_type2, b.cloud_no, c.page_no from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no join om_cloud_optimizer_rel_tbl c on b.resource_no = c.resource_no where b.resource_type !=0 and b.resource_org_size >0
AND b.site_no IN
CAST(#{item} AS INTEGER)
and rgstr_yyyy = #{rgstr_yyyy}
and rgstr_mm = #{rgstr_mm}
) a where a.resource_no != 0 and page_no != 0 group by resource_name,a.resource_no,resource_org_size,resource_new_size_type2,resource_status,cloud_no;

select resource_status, resource_name, resource_org_size, resource_new_size_type2, cloud_no, resource_type, count(*) as resource_call_cnt from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE -1 END AS resource_status, resource_org_size, resource_new_size_type2, resource_name, b.cloud_no, resource_type from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
) a where 1=1
and resource_status = #{resource_status}
group by resource_status, resource_name, resource_org_size, resource_new_size_type2, resource_type, cloud_no order by resource_type;

select resource_status, resource_name, resource_org_size, resource_new_size_type2, cloud_no, resource_type, page_no, count(*) as resource_call_cnt from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE -1 END AS resource_status, resource_org_size, resource_new_size_type2, resource_name, b.cloud_no, a.page_no, resource_type from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
) a where 1=1
and resource_status = #{resource_status}
and page_no = #{page_no}
group by resource_status, resource_name, resource_org_size, resource_new_size_type2, resource_type, cloud_no, page_no order by resource_type;

select resource_status, resource_name, resource_org_size, resource_new_size_type2, cloud_no, resource_type, count(*) as resource_call_cnt from ( select resource_status, resource_org_size, resource_new_size_type2, resource_name, b.cloud_no, resource_type from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type in
CAST(#{item} AS INTEGER)
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
) a where 1=1
and 1 > resource_status
group by resource_status, resource_name, resource_org_size, resource_new_size_type2, resource_type, cloud_no order by resource_type
LIMIT #{size} OFFSET #{offset}

select resource_status, resource_name, resource_org_size, resource_new_size_type2, cloud_no, resource_type, page_no, count(*) as resource_call_cnt from ( select resource_status, resource_org_size, resource_new_size_type2, resource_name, b.cloud_no, a.page_no, resource_type from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no where b.resource_org_size >= 0 and resource_type != 0
and resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
) a where 1=1
and resource_status = #{resource_status}
and page_no = #{page_no}
group by resource_status, resource_name, resource_org_size, resource_new_size_type2, resource_type, cloud_no, page_no order by resource_type;

select ( select CASE WHEN b.rgstr_dt >= a.updt_dt THEN 1 ELSE 0 END )as resource_status ,a.resource_type ,a.resource_name ,a.resource_org_size ,a.resource_new_size_type2 ,count(*) as resource_call_cnt,b.cloud_no from om_cloud_optimizer_tbl a join om_cloud_resource_log_tbl b on a.resource_no =b.resource_no where a.resource_org_size >=0 and a.resource_type != 0
and a.resource_type = #{resource_type}
AND b.site_no IN
CAST(#{item} AS INTEGER)
and b.rgstr_date >= #{startDate}
and #{endDate} >= b.rgstr_date
and b.rgstr_yyyy = #{rgstr_yyyy}
and b.rgstr_mm = #{rgstr_mm}
group by 1,a.resource_status ,a.resource_type ,a.resource_name ,a.resource_org_size ,a.resource_new_size_type2,b.cloud_no ;

select ( select CASE WHEN b.rgstr_dt >= a.updt_dt THEN 1 ELSE 0 END ) as resource_status ,a.resource_type ,a.resource_name ,a.resource_org_size ,a.resource_new_size_type2 ,b.page_no ,count(*) as resource_call_cnt,b.cloud_no from om_cloud_optimizer_tbl a join om_cloud_resource_log_tbl b on a.resource_no =b.resource_no where a.resource_org_size >=0 and a.resource_type != 0
AND b.site_no IN
CAST(#{item} AS INTEGER)
and b.rgstr_date >= #{startDate}
and #{endDate} >= b.rgstr_date
and b.rgstr_yyyy = #{rgstr_yyyy}
and b.rgstr_mm = #{rgstr_mm}
group by 1,a.resource_status ,a.resource_type ,a.resource_name ,a.resource_org_size ,a.resource_new_size_type2,b.page_no,b.cloud_no ;

select a.resource_type, count(*) as opt_cnt from
(select * from om_cloud_optimizer_tbl ocot
where resource_org_size >= 0
and ocot.site_no IN 

	#{site_no}
)a
where a.resource_type !=0 and a.resource_status = 1
group by a.resource_type;

select a.resource_type, count(*) as opt_cnt from
(select * from om_cloud_optimizer_tbl ocot
where resource_org_size >= 0
and ocot.site_no IN 

	#{site_no}
)a
where a.resource_type !=0
group by a.resource_type;

select count(*), a.resource_no, sum(a.resource_org_size) as resource_org_size, SUM( CASE WHEN a.resource_new_size_type1 != a.resource_new_size_type2 THEN a.resource_new_size_type2 ELSE 0 END ) AS resource_new_size_type2 from ( select ocrlt.resource_no, ocolt.resource_org_size, ocolt.resource_new_size_type1, ocolt.resource_new_size_type2, ocrlt.rgstr_dt from om_cloud_resource_log_tbl ocrlt join om_cloud_optimizer_tbl ocolt on ocrlt. resource_no = ocolt.resource_no where ocrlt.rgstr_dt >= #{rgstr_dt_st}::timestamp and ocrlt.rgstr_dt <= #{rgstr_dt}::timestamp
and ocolt.resource_org_size >= 0 and ocrlt.site_no IN
#{site_no}
)a group by a.resource_no

select sum(b.resource_org_size) as resource_org_size, b.cloud_payment from (select count(*), a.resource_no, SUM(a.resource_org_size) AS resource_org_size, max(oct.cloud_payment) as cloud_payment from ( select ocrlt.resource_no, ocolt.resource_org_size, ocolt.resource_new_size_type1, ocolt.resource_new_size_type2, ocrlt.rgstr_dt, ocrlt.cloud_no from om_cloud_resource_log_tbl ocrlt join om_cloud_optimizer_tbl ocolt on ocrlt. resource_no = ocolt.resource_no where ocrlt.rgstr_dt >= #{rgstr_dt_st}::timestamp and ocrlt.rgstr_dt <= #{rgstr_dt}::timestamp
and ocolt.resource_org_size >= 0 and ocrlt.site_no IN
#{site_no}
)a left join om_cloud_tbl oct on a.cloud_no = oct.cloud_no group by a.resource_no)b group by b.cloud_payment

select sum(b.resource_org_size) as resource_org_size, sum(b.resource_new_size_type2) as resource_new_size_type2, b.cloud_payment from (select count(*), a.resource_no, sum(a.resource_org_size) as resource_org_size, sum( case when a.resource_new_size_type1 != a.resource_new_size_type2 and a.resource_new_size_type2 > 0 THEN a.resource_new_size_type2 else a.resource_org_size end ) as resource_new_size_type2, max(oct.cloud_payment) as cloud_payment from ( select ocrlt.resource_no, ocolt.resource_org_size, ocolt.resource_new_size_type1, ocolt.resource_new_size_type2, ocrlt.rgstr_dt, ocrlt.cloud_no from om_cloud_resource_log_tbl ocrlt join om_cloud_optimizer_tbl ocolt on ocrlt. resource_no = ocolt.resource_no where ocrlt.rgstr_dt >= #{rgstr_dt_st}::timestamp and ocrlt.rgstr_dt <= #{rgstr_dt}::timestamp
and ocolt.resource_org_size >= 0 and ocrlt.site_no IN
#{site_no}
)a left join om_cloud_tbl oct on a.cloud_no = oct.cloud_no group by a.resource_no)b group by b.cloud_payment

select count(*) as cnt, ocrlt.rgstr_dt from om_cloud_resource_log_tbl ocrlt where ocrlt.rgstr_dt >= #{rgstr_dt}::timestamp and ocrlt.rgstr_dt <= #{rgstr_dt}::timestamp
and ocrlt.site_no IN
#{site_no}

select ROW_NUMBER() OVER (ORDER BY resource_name ) AS row_no, resource_name, a.resource_no, resource_type, resource_org_size, resource_new_size_type1, resource_new_size_type2, resource_status, count(*) as resource_call_cnt ,cloud_no from ( select CASE WHEN a.rgstr_dt >= b.updt_dt THEN 1 ELSE 0 END AS resource_status, a.resource_no, b.resource_name, resource_type, resource_org_size, resource_new_size_type1, resource_new_size_type2, b.cloud_no, c.page_no from public.om_cloud_resource_log_tbl a join public.om_cloud_optimizer_tbl b on a.resource_no = b.resource_no join om_cloud_optimizer_rel_tbl c on b.resource_no = c.resource_no where b.resource_type !=0 and b.resource_org_size >0
and a.rgstr_date >= #{startDate}
and #{endDate} >= a.rgstr_date
and a.rgstr_yyyy = #{rgstr_yyyy}
and a.rgstr_mm = #{rgstr_mm}
and a.rgstr_dd = #{rgstr_dd}
AND resource_type > 0
AND resource_parent_no = #{resource_parent_no}
and resource_status >0 ) a where a.resource_no != 0 and page_no != 0 group by resource_name,a.resource_no,resource_type,resource_org_size,resource_new_size_type1,resource_new_size_type2,resource_status,cloud_no
LIMIT #{size} OFFSET #{offset}

SELECT resource_parent_no, SUM(CASE WHEN 1 = 1 THEN 1 ELSE 0 END) AS count, COUNT(*) AS entire_count FROM om_cloud_optimizer_tbl ocot WHERE 1 = 1 AND resource_type > 0 and resource_no in (select resource_no from om_cloud_resource_log_tbl ocolt where 1=1
and ocolt.rgstr_date >= #{startDate}
and #{endDate} >= ocolt.rgstr_date
and ocolt.rgstr_yyyy = #{rgstr_yyyy}
and ocolt.rgstr_mm = #{rgstr_mm}
and ocolt.rgstr_dd = #{rgstr_dd}
AND resource_type != 0 and resource_status > 0 group by resource_no) and resource_org_size >= 0
GROUP BY resource_parent_no
